INSERT INTO "SiteSetting" (key,value,"updatedAt") VALUES ('openingBalance', jsonb_build_object('amountRsd',15000,'date','2026-09-01'), now()) ON CONFLICT (key) DO NOTHING;
UPDATE "SiteSetting" SET value = value || jsonb_build_object('cats', jsonb_build_array(jsonb_build_object('catId',(SELECT id FROM cats WHERE slug='nami'),'amountRsd',4082))), "updatedAt"=now() WHERE key='openingBalance';
-- checks
SELECT 'expenses without cat' AS check, count(*) FROM "Expense" e WHERE e."importKey" LIKE 'xlsx1:%' AND NOT EXISTS (SELECT 1 FROM "ExpenseCat" x WHERE x."expenseId"=e.id);
SELECT 'donations without cat' AS check, count(*) FROM "Donation" WHERE "importKey" LIKE 'xlsx1:%' AND "catId" IS NULL;
SELECT 'totals' AS check, (SELECT sum("amountRsd") FROM "Expense" WHERE "importKey" LIKE 'xlsx1:%') AS spent, (SELECT sum("amountRsd") FROM "Donation" WHERE "importKey" LIKE 'xlsx1:%') AS raised;
COMMIT;
